#!/usr/bin/env node
// Restore complete exact coincident source sets and allow bounded projected rounding. No network calls or external packages.
// Run beside src: node apply-places-coincident-restoration-fix.cjs --dry-run, then without flags.
// Offline Python tools only; no widget rebuild or Pro export is required. --uninstall restores this installation.
'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),zlib=require('node:zlib');
const entries=JSON.parse(zlib.gunzipSync(Buffer.from('','base64')));
const root=process.cwd(),args=new Set(process.argv.slice(2));
if([...args].some(a=>!['--dry-run','--uninstall'].includes(a)))throw Error('Use --dry-run or --uninstall');
if(!fs.existsSync(path.join(root,'src/runtime/widget.tsx')))throw Error('Run from the widget root, beside src.');
const hash=b=>crypto.createHash('sha1').update(Buffer.from('blob '+b.length+'\0')).update(b).digest('hex');
function matches(buffer,expected){
 if(!expected)return buffer===null;
 if(buffer===null)return false;
 if(hash(buffer)===expected)return true;
 if(buffer.includes(0))return false;
 const normalized=Buffer.from(buffer.toString('utf8').replace(/\r\n/g,'\n'));
 if(hash(normalized)===expected)return true;
 return normalized.subarray(0,3).equals(Buffer.from([239,187,191]))&&hash(normalized.subarray(3))===expected;
}
function local(file){
 const destination=path.resolve(root,file);
 if(!destination.startsWith(root+path.sep))throw Error('Unsafe path: '+file);
 for(let p=destination;p!==root;p=path.dirname(p))if(fs.existsSync(p)&&fs.lstatSync(p).isSymbolicLink())throw Error('Symbolic link is not supported: '+file);
 return destination;
}
const read=file=>fs.existsSync(file)?fs.readFileSync(file):null;
const backupRoot=path.resolve(root,'..','.map-ex-places-coincident-backups',path.basename(root)+'-'+crypto.createHash('sha256').update(root).digest('hex').slice(0,10));
const stateFile=path.join(backupRoot,'state.json');
function write(file,data){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,data);}
function prune(file){let dir=path.dirname(file);while(dir!==root&&dir.startsWith(root+path.sep)){if(!fs.existsSync(dir)||fs.readdirSync(dir).length)break;fs.rmdirSync(dir);dir=path.dirname(dir);}}
const state=fs.existsSync(stateFile)?JSON.parse(fs.readFileSync(stateFile,'utf8')):null;
if(state&&state.root!==root)throw Error('Backup belongs to another widget directory.');
if(args.has('--uninstall')){
 if(!state){console.log('No cleanup installation found for this folder.');process.exit(0);}
 const changed=state.files.map(record=>({...record,target:local(record.file)}));
 const conflicts=changed.filter(record=>!matches(read(record.target),record.after));
 if(conflicts.length)throw Error('Rollback would overwrite later edits. No files changed:\n'+conflicts.map(e=>e.file).join('\n'));
 for(const record of changed)if(record.existed){const saved=read(path.join(backupRoot,'files',record.file));if(saved===null||hash(saved)!==record.backupHash)throw Error('Backup missing or altered: '+record.file);}
 if(args.has('--dry-run')){console.log('Rollback check passed for '+changed.length+' files.');process.exit(0);}
 for(const record of changed){if(record.existed)write(record.target,read(path.join(backupRoot,'files',record.file)));else if(fs.existsSync(record.target)){fs.unlinkSync(record.target);prune(record.target);}}
 fs.unlinkSync(stateFile);console.log('Exact pre-install files restored. No widget rebuild is required.');process.exit(0);
}
const changes=[],conflicts=[];
for(const entry of entries){
 const target=local(entry.file),current=read(target);
 if(matches(current,entry.after))continue;
 // An already absent retired file needs no action.
 if(entry.after===null&&current===null)continue;
 if(!matches(current,entry.before)){conflicts.push(entry.file);continue;}
 changes.push({...entry,target,current});
}
if(conflicts.length)throw Error('Source differs from the supported initial restoration workflow. Unknown local edits were preserved. No files changed:\n'+conflicts.slice(0,30).join('\n')+(conflicts.length>30?'\n... '+conflicts.length+' total conflicts':''));
if(!changes.length){console.log('Coincident restoration fix is already applied.');process.exit(0);}
if(state)throw Error('A partial later change exists. Restore/review the prior installation before applying again.');
if(args.has('--dry-run')){console.log('Check passed: '+changes.length+' files to update/remove. No files changed.');process.exit(0);}
fs.mkdirSync(backupRoot,{recursive:true});
const records=changes.map(e=>({file:e.file,after:e.after,existed:e.current!==null,backupHash:e.current===null?null:hash(e.current)}));
// Back up every existing target before changing any source.
for(const e of changes)if(e.current!==null)write(path.join(backupRoot,'files',e.file),e.current);
try{
 for(const e of changes){if(e.after===null){fs.unlinkSync(e.target);prune(e.target);}else write(e.target,Buffer.from(e.data,'base64'));}
 write(stateFile,JSON.stringify({root,base:'initial attribute restoration workflow',files:records},null,2));
}catch(error){
 for(const e of changes){if(e.current!==null)write(e.target,e.current);else if(fs.existsSync(e.target)){fs.unlinkSync(e.target);prune(e.target);}}
 throw error;
}
console.log('Coincident restoration fix applied. '+changes.length+' files updated/removed.');
console.log('Backups: '+backupRoot);
console.log('Repair the existing native package using the exact source GeoJSON. No widget rebuild or Pro export is required. Rollback: node apply-places-coincident-restoration-fix.cjs --uninstall');
